urlset:
{% spaceless %}
{% for url in urlset %}

    {{ url.location }}
    {% if url.lastmod %}{{ url.lastmod|date:"c" }}{% endif %}
    {% if url.changefreq %}{{ url.changefreq }}{% endif %}
    {% if url.priority %}{{ url.priority }}{% endif %}
    {% for alt in url.alternates %}{% endfor %}
    {% for image in url.images %}{{ image.loc }}{% endfor %}

{% endfor %}
{% endspaceless %}
